package com.bank.integrity.service;

import com.bank.integrity.model.TxnNode;
import java.util.logging.Logger;

// Detects a cycle in a transaction chain using Floyd's tortoise and hare.
public class ChainIntegrityChecker {
    private static final Logger log = Logger.getLogger(ChainIntegrityChecker.class.getName());

    public boolean hasCycle(TxnNode head) {
        TxnNode slow = head;
        TxnNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;          // one step
            fast = fast.next.next;     // two steps
            if (slow == fast) {        // they met inside a loop
                log.severe("Cycle detected in transaction chain.");
                return true;
            }
        }
        log.info("No cycle; chain is clean.");
        return false;
    }
}
