package com.bank.integrity;

import com.bank.integrity.model.TxnNode;
import com.bank.integrity.service.ChainIntegrityChecker;
import java.util.logging.Logger;

public class ChainIntegrityDemo {
    private static final Logger log = Logger.getLogger(ChainIntegrityDemo.class.getName());

    public static void main(String[] args) {
        ChainIntegrityChecker checker = new ChainIntegrityChecker();

        // Clean chain: T1 -> T2 -> T3 -> T4 -> null
        TxnNode t1 = new TxnNode("T1");
        TxnNode t2 = new TxnNode("T2");
        TxnNode t3 = new TxnNode("T3");
        TxnNode t4 = new TxnNode("T4");
        t1.next = t2; t2.next = t3; t3.next = t4;
        log.info(() -> "Clean chain has cycle: " + checker.hasCycle(t1));

        // Corrupted chain: T4 points back to T2 (loop).
        t4.next = t2;
        log.info(() -> "Corrupted chain has cycle: " + checker.hasCycle(t1));
    }
}
